'use strict';

const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(tokens[0]);
const digits = tokens.slice(1).join('');

function increment(s) {
  const chars = s.split('');
  let i = chars.length - 1;

  while (i >= 0 && chars[i] === '9') {
    chars[i] = '0';
    i--;
  }

  if (i < 0) return '1' + chars.join('');
  chars[i] = String.fromCharCode(chars[i].charCodeAt(0) + 1);
  return chars.join('');
}

for (let len = 1; len <= n; len++) {
  if (digits[0] === '0') break;

  const start = digits.slice(0, len);
  let pos = len;
  let current = increment(start);
  let valid = true;

  while (pos < n) {
    if (current.length > n - pos || !digits.startsWith(current, pos)) {
      valid = false;
      break;
    }
    pos += current.length;
    current = increment(current);
  }

  if (valid) {
    console.log(start);
    process.exit(0);
  }
} 
